SET FOREIGN_KEY_CHECKS=0;

DELETE t1
FROM `roles_and_permission` t1
JOIN `roles_and_permission` t2
ON  t1.login_type      = t2.login_type
AND t1.permission_type = t2.permission_type
AND t1.menu_name       = t2.menu_name
AND t1.module_name     = t2.module_name
AND t1.sub_module_name = t2.sub_module_name
AND t1.module_url      = t2.module_url
AND t1.id > t2.id;

UPDATE `roles_and_permission`
SET menu_name       = TRIM(menu_name),
    module_name     = TRIM(module_name),
    sub_module_name = TRIM(sub_module_name),
    module_url      = TRIM(module_url)
WHERE menu_name       <> TRIM(menu_name)
   OR module_name     <> TRIM(module_name)
   OR sub_module_name <> TRIM(sub_module_name)
   OR module_url      <> TRIM(module_url);

ALTER TABLE `roles_and_permission`
	ADD UNIQUE KEY `uq_rp_identity`
	(`login_type`, `permission_type`, `menu_name`, `module_name`, `sub_module_name`, `module_url`);

ALTER TABLE `permissions_types`
	ADD UNIQUE KEY `uq_pt_identity`
	(`permission_type_code`, `permission_name`);


	INSERT INTO `permissions_types` (`permission_type_code`, `permission_name`, `reseller_id`, `status`) VALUES ('1', 'Super Admin', 0, 0)
	  ON DUPLICATE KEY UPDATE `permission_name` = VALUES(`permission_name`), `status` = VALUES(`status`);
	
	INSERT INTO `permissions_types` (`permission_type_code`, `permission_name`, `reseller_id`, `status`) VALUES ('2', 'Sub Admin', 0, 0)
	  ON DUPLICATE KEY UPDATE `permission_name` = VALUES(`permission_name`), `status` = VALUES(`status`);
	
	INSERT INTO `permissions_types` (`permission_type_code`, `permission_name`, `reseller_id`, `status`) VALUES ('3', 'Reseller', 0, 0)
	  ON DUPLICATE KEY UPDATE `permission_name` = VALUES(`permission_name`), `status` = VALUES(`status`);


START TRANSACTION;

